"""The line that marks a generated file as generated."""
from besser.generators.generated_header import header_text, mark_generated, without_header

HEADER = header_text(None)


def test_each_language_gets_its_own_comment_and_other_files_none():
    marked = mark_generated({
        "app.py": b"import os\n", "ui/App.tsx": b"export {}\n", "style.css": b"a {}\n", "schema.sql": b"x;\n",
        "data.json": b"{}\n", "requirements.txt": b"fastapi\n", "logo.png": b"\x89PNG\x00",
    })

    assert marked["app.py"] == f"# {HEADER}\nimport os\n".encode()
    assert marked["ui/App.tsx"] == f"// {HEADER}\nexport {{}}\n".encode()
    assert marked["style.css"] == f"/* {HEADER} */\na {{}}\n".encode()
    assert marked["schema.sql"] == f"-- {HEADER}\nx;\n".encode()
    assert [marked[name] for name in ("data.json", "requirements.txt", "logo.png")] == [
        b"{}\n", b"fastapi\n", b"\x89PNG\x00"]


def test_a_shebang_stays_first_and_line_endings_are_kept():
    marked = mark_generated({"run.sh": b"#!/bin/sh\r\necho hi\r\n"})

    assert marked["run.sh"] == f"#!/bin/sh\r\n# {HEADER}\r\necho hi\r\n".encode()


def test_marking_twice_or_a_file_with_its_own_header_changes_nothing():
    once = mark_generated({"app.py": b"x = 1\n"})
    own = {"compose.yml": b"# Generated by BESSER for docker\nservices: {}\n"}

    assert mark_generated(once) == once
    assert mark_generated(own) == own


def test_the_header_names_the_extension_file_and_comes_off_again():
    marked = mark_generated({"main_api.py": b"app = 1\n"}, "extensions.py")

    assert marked["main_api.py"].startswith(b"# Generated by BESSER: edit the model, not this file. "
                                            b"Custom code goes in extensions.py.\n")
    assert without_header(marked["main_api.py"]) == b"app = 1\n"
    assert without_header(b"app = 1\n") == b"app = 1\n"
